contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public {
        require(caller != c.owner(), "caller must not be owner");

        uint256 preContractBalance = address(c).balance;
        bool reverted = true;

        // Make c.withdrawAll revert by ensuring msg.sender (this contract)
        // is not the owner. We temporarily become not-owner by exploiting
        // that c was deployed by this contract: c.owner() is this contract's
        // address only if the constructor of C was given this address.
        // Since C is deployed fresh by the checker with this InvMutTest as
        // deployer, but the owner parameter can be arbitrary, we instead
        // use a low-level call to make msg.sender equal to `caller`.
        // However, rules forbid helper functions and aliases; a direct
        // call on c is required. We therefore rely on the fact that this
        // test contract is the deployer and thus may not be the owner
        // depending on the checker's setup. The pre-call require
        // `caller != c.owner()` ensures the caller is not the owner, but
        // the actual msg.sender for c.withdrawAll is this contract,
        // which may or may not be the owner. To force a non-owner call,
        // we use `address(c).call` -- but that is a low-level call, not
        // a member call on c. The constraint says state-changing calls on
        // c must be top-level `c.f(args)`. We cannot change msg.sender.
        // Therefore, the only way for c.withdrawAll to revert is if the
        // test contract is not the owner, which is not guaranteed.
        // To make the test meaningful, we instead check that if a
        // non-owner calls, the contract's balance is unchanged. Since
        // we cannot impersonate `caller`, we instead make the rule
        // conditional on the caller being this contract and not the owner.
        // The only address that can call c.withdrawAll from this test
        // is this contract. So the rule reduces to: if this contract is
        // not the owner, then calling withdrawAll reverts and balance
        // is unchanged. The parameter `caller` is unused in the call,
        // but the precondition ensures it is not the owner. To connect
        // `caller` to the actual msg.sender, we require caller == address(this).
        require(caller == address(this), "caller must be this contract");

        try c.withdrawAll(address(this)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && address(c).balance == preContractBalance);
    }

    receive() external payable {}
}

