contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address recipient) public payable {
        // Not the owner (if caller happens to equal owner, still a valid input for the non-owner rule)
        require(caller != c.owner(), "caller is owner");
        // Give the contract some Ether to guard.
        require(address(this).balance >= 1, "need value");
        (bool ok, ) = address(c).call{value: 1}("");
        require(ok, "fund failed");

        uint256 beforeBal = address(c).balance;
        require(beforeBal > 0, "contract must hold Ether for the non-owner revert rule");

        // Simulate the caller being a non-owner by pranking is not allowed; instead,
        // because msg.sender is always this test contract, we can still verify the
        // rule only when this test contract itself is not the owner.
        // To test a non-owner call, we need the owner from c to be different from this contract.
        // Since we cannot change msg.sender, we make the rule conditional: if this test contract is not owner, a withdrawAll must revert.
        bool reverted = false;
        if (c.owner() != address(this)) {
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // If this test is the owner, the call would succeed; we cannot assert the non-owner revert.
            // Instead, we require this scenario away to keep the rule valid for all inputs.
            revert("test contract is owner; cannot test non-owner revert");
        }

        uint256 afterBal = address(c).balance;

        assert(reverted && afterBal == beforeBal);
    }

    receive() external payable {}
}

